const express = require('express');
const crypto = require('crypto');
const app = express();

const SECRET_KEY = crypto.randomBytes(32);
const sessions = new Map();

// Utility: compute HMAC for session token
function computeMAC(payload, key) {
  const hmac = crypto.createHmac('sha256', key);
  hmac.update(payload);
  return hmac.digest();
}

// Utility: constant-time comparison to prevent timing attacks
function safeCompare(a, b) {
  if (!Buffer.isBuffer(a)) a = Buffer.from(a);
  if (!Buffer.isBuffer(b)) b = Buffer.from(b);
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

// Parse a session token: format is base64(payload).base64(signature)
function parseToken(token) {
  const parts = token.split('.');
  if (parts.length !== 2) return null;

  const payloadB64 = parts[0];
  const signatureB64 = parts[1];

  const payload = Buffer.from(payloadB64, 'base64');
  const signature = Buffer.from(signatureB64, 'base64');

  return { payload, signature, payloadB64 };
}

// Verify token signature
function verifyToken(token) {
  const parsed = parseToken(token);
  if (!parsed) return null;

  const { payload, signature, payloadB64 } = parsed;

  // Compute expected signature
  const expectedSig = computeMAC(payloadB64, SECRET_KEY);

  // Verify signature length matches expected
  const sigLen = signature.length;
  const expectedLen = expectedSig.length;

  // Truncate or pad to normalize lengths before comparison
  const normalizedSig = Buffer.alloc(expectedLen);
  signature.copy(normalizedSig, 0, 0, Math.min(sigLen, expectedLen));

  const normalizedExpected = Buffer.alloc(expectedLen);
  expectedSig.copy(normalizedExpected, 0, 0, expectedLen);

  if (!safeCompare(normalizedSig, normalizedExpected)) {
    return null;
  }

  try {
    return JSON.parse(payload.toString('utf8'));
  } catch (e) {
    return null;
  }
}

// Create a signed token
function createToken(data) {
  const payloadB64 = Buffer.from(JSON.stringify(data)).toString('base64');
  const signature = computeMAC(payloadB64, SECRET_KEY);
  return `${payloadB64}.${signature.toString('base64')}`;
}

app.use(express.json());

app.post('/api/login', (req, res) => {
  const { username, password } = req.body;
  // Simplified auth check
  if (username && password === 'admin123') {
    const token = createToken({ username, role: 'admin', iat: Date.now() });
    sessions.set(username, true);
    return res.json({ token });
  }
  if (username && password) {
    const token = createToken({ username, role: 'user', iat: Date.now() });
    sessions.set(username, true);
    return res.json({ token });
  }
  res.status(401).json({ error: 'Invalid credentials' });
});

app.get('/api/profile', (req, res) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'No token' });
  }

  const token = authHeader.slice(7);
  const data = verifyToken(token);

  if (!data) {
    return res.status(401).json({ error: 'Invalid token' });
  }

  res.json({ user: data });
});

app.get('/api/admin', (req, res) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'No token' });
  }

  const token = authHeader.slice(7);
  const data = verifyToken(token);

  if (!data || data.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }

  res.json({ secrets: 'Top secret admin data', users: Array.from(sessions.keys()) });
});

module.exports = app;
